function renderAdoptionConfiguration(brief) {
  const layers=(brief.layers||[]).map((layer,index)=>({layer,index})).filter(item=>item.layer.enabled);
  return `<section class="generation-quantity adoption-configuration"><div class="quantity-head"><div><strong>FMOD 采用目标</strong><span>这里配置最终进入 Event 的样本数量，与生成候选数量相互独立</span></div><div class="adoption-policies"><span>快捷策略</span><button type="button" data-adoption-policy="Single">单样本 · 1</button><button type="button" data-adoption-policy="Standard">标准变化集</button><button type="button" data-adoption-policy="Varied">高频防重复 · 6</button></div></div><div class="layer-count-grid">${layers.map(({layer,index})=>`<article><strong>${esc(layer.name)}</strong><label class="field"><span>从 ${layer.takes} 个候选中采用</span><input type="number" min="1" max="${layer.takes}" value="${layer.adoptionTakes}" data-generation-layer-count="${index}" data-count-kind="adoptionTakes"></label><small>${layer.adoptionTakes===1?"Single Instrument · 不随机":`Multi Instrument · ${layer.adoptionTakes} 个随机变化`}</small></article>`).join("")}</div><p class="notice">采用 1 个时创建 Single Instrument，不添加随机调制；采用 2 个以上才创建随机 Multi Instrument。</p></section>`;
}
function detectCollisionKind(cue, brief) {
  const text = `${cue?.audioCueId || ""} ${cue?.displayName || ""} ${cue?.purpose || ""} ${(cue?.tags || []).join(" ")} ${brief?.category || ""}`.toLowerCase();
  if (text.includes("fireball") || text.includes("explosion")) return "";
  if (/foot|sole|step/.test(text)) return "Footstep";
  if (/landing|落地/.test(text)) return "Landing";
  if (/collision/.test(text)) return "ObjectCollision";
  if (/weapon|attack|blocked|\bhit\b/.test(text)) return "WeaponHit";
  return "";
}

function semanticCollisionProfile(cue, brief) {
  const kind = detectCollisionKind(cue, brief); if (!kind) return null;
  const text = `${cue.audioCueId} ${cue.displayName} ${cue.purpose || ""} ${(cue.tags || []).join(" ")}`.toLowerCase();
  const receiver = { materialId:"auto",customMaterial:"",massClass:["Footstep","Landing"].includes(kind)?"massive":"medium",contactArea:kind==="Footstep"?"small":"medium",surface:"normal",construction:"solid" };
  if (/elastic|弹性/.test(text)) Object.assign(receiver,{materialId:"rubber",construction:"soft_filled"});
  else if (/hard[- ]slick/.test(text)) Object.assign(receiver,{materialId:"generic_solid",surface:"smooth"});
  else if (/rough|粗糙/.test(text)) receiver.surface="rough";
  else if (/stone|concrete/.test(text)) receiver.materialId="stone_concrete";
  else if (/metal/.test(text)) receiver.materialId="metal";
  const impactor={materialId:kind==="Footstep"?"cloth_leather":kind==="WeaponHit"?"metal":"auto",customMaterial:"",massClass:"medium",contactArea:["Footstep","WeaponHit"].includes(kind)?"small":"medium",surface:"normal",construction:["Footstep","Landing"].includes(kind)?"soft_filled":"solid"};
  const mode=/blocked|格挡/.test(text)?"block":kind==="Footstep"?"step":kind==="Landing"?"land":kind==="WeaponHit"?"weapon_hit":"impact";
  return {kind,impactor,receiver,interaction:{intensity:"medium",speed:"medium",angle:"direct",mode}};
}

function normalizeCollisionRecipe(brief, cue=selectedCue()) {
  if (!brief) return;
  const created=!brief.collisionProfile;
  brief.collisionProfile ||= semanticCollisionProfile(cue, brief);
  const profile=brief.collisionProfile;if(!profile)return;
  profile.impactor ||= {};profile.receiver ||= {};profile.interaction ||= {};
  for(const body of [profile.impactor,profile.receiver]) Object.assign(body,{materialId:"auto",customMaterial:"",massClass:"medium",contactArea:"medium",surface:"normal",construction:"solid"},body);
  Object.assign(profile.interaction,{intensity:"medium",speed:"medium",angle:"direct",mode:"impact"},profile.interaction);
  syncCollisionLegacy(brief);
  if(created){if(brief.promptModified)state.collisionPromptStale.add(brief.audioCueId);else rebuildCollisionPrompts(brief);}
}

function collisionRoles(kind){return kind==="Footstep"?["鞋底","地面"]:kind==="Landing"?["落地角色","地面"]:kind==="WeaponHit"?["武器","目标"]:["碰撞体","受体"];}
function optionLabel(group,value){return (COLLISION_OPTIONS[group]||COLLISION_MATERIALS).find(item=>item[0]===value)?.[1]||value||"自动";}
function collisionSummary(profile){const roles=collisionRoles(profile.kind),a=profile.impactor,b=profile.receiver,i=profile.interaction;return `${optionLabel("massClass",a.massClass)}质量${optionLabel("construction",a.construction)}${roles[0]}，${optionLabel("angle",i.angle)}${optionLabel("mode",i.mode)}${optionLabel("surface",b.surface)}${optionLabel("material",b.materialId)}${roles[1]}，强度${optionLabel("intensity",i.intensity)}`;}
function renderChoiceGroup(scope,field,value,options){return `<div class="physical-control"><span>${field==="massClass"?"质量":field==="contactArea"?"接触面积":field==="surface"?"表面":field==="construction"?"构造":field==="intensity"?"强度":field==="speed"?"速度":field==="angle"?"角度":"接触方式"}</span><div class="segmented compact">${options.map(([id,label])=>`<button type="button" class="${value===id?"active":""}" data-collision-scope="${scope}" data-collision-field="${field}" data-collision-value="${id}">${label}</button>`).join("")}</div></div>`;}
function renderCollisionBody(side,label,body){return `<article class="collision-body-card"><header><span>${side==="impactor"?"A":"B"}</span><div><strong>${label}</strong><small>${side==="impactor"?"发起接触并提供主要运动能量":"接收冲击并决定共振与尾音"}</small></div></header><label class="field"><span>材质</span><select data-collision-body="${side}" data-collision-body-field="materialId">${COLLISION_MATERIALS.map(([id,name])=>`<option value="${id}"${body.materialId===id?" selected":""}>${name}</option>`).join("")}</select></label>${body.materialId==="custom"?`<label class="field"><span>自定义材质描述</span><input data-collision-body="${side}" data-collision-body-field="customMaterial" value="${esc(body.customMaterial||"")}"></label>`:""}${renderChoiceGroup(side,"massClass",body.massClass,COLLISION_OPTIONS.massClass)}${renderChoiceGroup(side,"contactArea",body.contactArea,COLLISION_OPTIONS.contactArea)}${renderChoiceGroup(side,"surface",body.surface,COLLISION_OPTIONS.surface)}${renderChoiceGroup(side,"construction",body.construction,COLLISION_OPTIONS.construction)}</article>`;}

function inferredDecayProfile(brief){const ids=[brief.collisionProfile?.impactor?.materialId,brief.collisionProfile?.receiver?.materialId];if(brief.category==="AirDisplacement")return"Sweep";if(ids.includes("magic_energy"))return"Magic";if(ids.includes("metal"))return"Resonant";if(ids.includes("soil_sand"))return"Granular";if(ids.some(id=>["glass_ceramic","ice"].includes(id)))return"Brittle";if(ids.some(id=>["rubber","cloth_leather","flesh"].includes(id)))return"Short";return"Natural";}
function recommendedLayerMax(brief,layerName="body"){const kind=brief.collisionProfile?.kind||brief.category,profile=inferredDecayProfile(brief);if(["Scrape","Roll","Compression"].includes(kind))return 3;if(kind==="Footstep")return.4;if(kind==="Landing")return layerName==="transient"?.18:.55;if(kind==="WeaponHit"){const blocked=brief.collisionProfile?.interaction?.mode==="block"||/block/i.test(brief.action||"");return layerName==="transient"?(blocked?.18:.15):layerName==="tail"?.65:blocked?.5:.45;}if(kind==="ObjectCollision")return({Short:.22,Natural:.3,Brittle:.38,Granular:.42,Resonant:.45,Magic:.5})[profile]||.3;if(kind==="AirDisplacement")return profile==="Magic"?.6:.45;if(kind==="Explosion")return 1.5;if(/loop|demo/i.test(`${brief.category} ${brief.action}`))return 3;return.8;}
function durationPolicy(brief){const kind=brief.collisionProfile?.kind||brief.category,recommended=recommendedLayerMax(brief);return ["Scrape","Roll","Compression"].includes(kind)?{min:1,max:30,step:.5,recommended}:kind==="Footstep"?{min:.12,max:1,step:.01,recommended}:kind==="ObjectCollision"?{min:.12,max:.8,step:.01,recommended}:["Landing","WeaponHit"].includes(kind)?{min:.12,max:1.2,step:.01,recommended}:kind==="AirDisplacement"?{min:.2,max:1,step:.01,recommended}:kind==="Explosion"?{min:.4,max:4,step:.05,recommended}:/loop|demo/i.test(`${brief.category} ${brief.action}`)?{min:1,max:30,step:.5,recommended}:{min:.1,max:3,step:.05,recommended};}
function renderDurationControl(brief){const p=durationPolicy(brief),value=Math.max(p.min,Math.min(p.max,Number(brief.maxDurationSeconds||brief.targetDurationSeconds||p.recommended))),mode=brief.durationMode||"LegacyFixed",character=brief.durationCharacter||"Auto",profile=brief.decayProfile||inferredDecayProfile(brief);return `<section class="duration-control wide"><div><div><strong>最大生成窗口</strong><small>${mode==="NaturalDecay"?`自然衰减 · ${esc(profile)}`:"历史固定时长"}</small></div><output data-duration-output>${value.toFixed(2)} 秒</output></div><input type="range" min="${p.min}" max="${p.max}" step="${p.step}" value="${value}" data-generation-duration><div class="duration-scale"><span>${p.min.toFixed(2)}s</span><span>推荐上限 ${p.recommended.toFixed(2)}s</span><span>${p.max.toFixed(2)}s</span></div><div class="duration-presets">${[["Auto","自动"],["Shorter","更短促"],["Natural","自然"],["Extended","更延展"]].map(([id,label])=>`<button type="button" data-duration-character="${id}" class="${character===id?"active":""}">${label}</button>`).join("")}</div><p class="duration-hint">模型仍在稳定 5 秒画布生成；成品在此上限内按自然衰减自动结束，不补静音、不补尾音。</p><details><summary>精确输入与逐层上限</summary><label class="field"><span>整体上限（秒）</span><input type="number" min="${p.min}" max="${p.max}" step="${p.step}" value="${value}" data-generation-duration-exact></label><div class="layer-duration-list">${(brief.layers||[]).filter(item=>item.enabled).map((layer,index)=>`<label class="field"><span>${esc(layer.name)}</span><input type="number" min="0.03" max="30" step="0.01" value="${Number(layer.maxDurationSeconds||recommendedLayerMax(brief,layer.name)).toFixed(2)}" data-layer-duration="${index}"></label>`).join("")}</div></details></section>`;}

function renderCollisionRecipe(cue,brief){const p=brief.collisionProfile,roles=collisionRoles(p.kind),stale=state.collisionPromptStale.has(cue.audioCueId);return `<section class="collision-overview wide"><div><span class="eyebrow">智能识别 · 接触音效</span><strong>${roles[0]} × ${roles[1]}</strong><p data-collision-summary>${esc(collisionSummary(p))}</p></div><div>${badge(p.kind,"info")}${badge("来源：Cue 名称 / 用途 / 标签")}</div><button type="button" data-generation-action="reset-physical">恢复语义默认值</button></section>${stale?`<div class="notice warn physical-prompt-stale wide"><span>物理配方已变化，人工英文 Prompt 尚未更新。</span><button type="button" data-generation-action="rebuild-physical">按当前参数重建</button></div>`:""}<section class="collision-pair-presets wide"><strong>常用组合</strong><div>${COLLISION_PAIR_PRESETS.map(([id,label])=>`<button type="button" data-collision-preset="${id}">${label}</button>`).join("")}</div></section><div class="collision-body-grid wide">${renderCollisionBody("impactor",roles[0],p.impactor)}${renderCollisionBody("receiver",roles[1],p.receiver)}</div><section class="collision-interaction wide"><header><div><strong>本次接触</strong><span>强度决定整体能量；速度影响瞬态锐度，角度影响擦碰比例。</span></div></header>${renderChoiceGroup("interaction","intensity",p.interaction.intensity,COLLISION_OPTIONS.intensity)}${renderChoiceGroup("interaction","speed",p.interaction.speed,COLLISION_OPTIONS.speed)}${renderChoiceGroup("interaction","angle",p.interaction.angle,COLLISION_OPTIONS.angle)}${renderChoiceGroup("interaction","mode",p.interaction.mode,COLLISION_OPTIONS.mode)}</section>${renderDurationControl(brief)}<details class="engineering wide"><summary>高级覆盖 · 类别 / 声源 / 声音方向</summary><div class="generation-grid"><label class="field"><span>类别</span><input data-generation-field="category" value="${esc(brief.category)}"></label><label class="field"><span>动作 / 声源</span><input data-generation-field="action" value="${esc(brief.action)}"></label><label class="field wide"><span>声音方向</span><input data-generation-field="soundDirection" value="${esc(brief.soundDirection)}"></label></div></details>`;}
function renderGenericRecipe(brief){return `<label class="field"><span>类别</span><input data-generation-field="category" value="${esc(brief.category)}"></label><label class="field"><span>动作 / 声源</span><input data-generation-field="action" value="${esc(brief.action)}"></label><label class="field"><span>材质</span><input data-generation-field="material" value="${esc(brief.material)}"></label><label class="field"><span>重量</span><input data-generation-field="weight" value="${esc(brief.weight)}"></label><label class="field"><span>强度</span><input data-generation-field="intensity" value="${esc(brief.intensity)}"></label><label class="field"><span>声音方向</span><input data-generation-field="soundDirection" value="${esc(brief.soundDirection)}"></label>${renderDurationControl(brief)}`;}

function renderGenerationPanel(cue, eventDef, workspaceTab = "") {
  const brief = state.generationBriefs.get(cue.audioCueId);
  const job = state.generationCueId === cue.audioCueId ? state.generationJob : null;
  const host = state.generationHealth;
  const hostReady = host?.status === "ok";
  const staleRecipe = brief && brief.bindingHash && brief.bindingHash !== bindingHash(cue.audioCueId);
  const hostText = hostReady ? `${host.model || "Stable Audio"} · ${host.gpuPolicy || "on-demand"} · Voice ${host.voiceReady ? "Ready" : "Unavailable"}` : host?.message || state.generationHealthError || "正在检查 4080 SFX Host…";
  const bootstrap = state.generationBootstrap || host?.bootstrapStatus;
  const bootstrapping = bootstrap && !["Ready", "Failed"].includes(bootstrap.status);
  const bootstrapProgress = Math.max(0, Math.min(100, Number(bootstrap?.progress || 0)));
  const bootstrapPanel = bootstrap ? `<div class="generation-bootstrap ${bootstrap.status === "Failed" ? "failed" : ""}"><div class="generation-bootstrap-head"><strong>${esc(bootstrap.message || "正在启动 SFX Host")}</strong><span>${esc(bootstrap.status)} · ${bootstrapProgress}%</span></div><progress max="100" value="${bootstrapProgress}"></progress><div class="bootstrap-steps"><span class="${bootstrapProgress >= 5 ? "done" : ""}">检查主机</span><i>→</i><span class="${bootstrapProgress >= 25 ? "done" : ""}">同步服务</span><i>→</i><span class="${bootstrapProgress >= 45 ? "done" : ""}">启动计划任务</span><i>→</i><span class="${bootstrapProgress >= 50 ? "done" : ""}">等待 10188</span></div>${bootstrap.code ? `<p class="notice error">${esc(bootstrap.code)}</p>` : ""}</div>` : "";
  const offlineNotice = host?.status === "offline" ? `<div class="generation-offline" role="status"><div><strong>${bootstrapping ? "正在冷启动 SFX 生成服务" : "SFX 生成服务未连接"}</strong><p>当前无法生成新候选；Cue 编辑、保存和 Unity / FMOD 试听仍可使用。</p></div><button type="button" data-generation-action="reconnect"${bootstrapping || host.startupAvailable === false ? " disabled" : ""}>${bootstrap?.status === "Failed" ? "重试启动" : "启动服务"}</button>${bootstrapPanel}<div class="bootstrap-actions"><button type="button" data-generation-action="copy-start">复制启动命令</button><button type="button" data-generation-action="show-diagnostics">查看启动诊断</button></div><details data-generation-diagnostics><summary>技术详情</summary><div class="kv"><div><span>Endpoint</span><strong><code>${esc(host.endpoint || "192.168.1.200:10188")}</code></strong></div><div><span>错误码</span><strong><code>${esc(bootstrap?.code || host.code || "AUDIO_GENERATION_HOST_UNAVAILABLE")}</code></strong></div></div><p class="notice error">${esc(bootstrap?.detail || host.detail || "生成主机没有响应。")}</p></details></div>` : "";
  const voiceServices = (job?.voiceServices || host?.voiceServices || []).map(service => badge(`${service.name}: ${service.health ? "在线" : service.restored ? "已恢复" : "冷停"}`, service.health || service.restored ? "ok" : "")).join("");
  if (!brief) {
    queueGenerationBrief(cue, eventDef);
    return `<div class="generation-panel"><div class="generation-head"><div><strong>Authoring AI Assist · 生成候选</strong><span>${esc(hostText)}</span></div><button type="button" data-generation-action="derive">生成 Brief</button></div>${offlineNotice}<div class="waveform-loading">正在根据 Cue 语义派生 sound brief…</div></div>`;
  }
  normalizeCollisionRecipe(brief, cue);
  normalizeRecipeCounts(brief);
  const candidates = job?.candidates || [];
  const terminal = ["Succeeded","Failed","Cancelled"].includes(job?.status);
  const hasReadyCandidates = candidates.some(candidateIsReady);
  const hasReviewableCandidates = candidates.some(candidateIsReviewable);
  const displayedJobStatus = !hasReadyCandidates && hasReviewableCandidates ? "已生成 · 需修剪" : candidates.length && !hasReadyCandidates ? "质量失败" : (job?.status || "Idle");
  const totalGenerated = generationTotal(brief);
  const totalAdoption = adoptionTotal(brief);
  const activeTab = workspaceTab || state.generationTabs.get(cue.audioCueId) || "recipe";
  const candidateGroups = candidates.length ? (brief.layers || []).filter(layer=>layer.enabled).map(layer => {
    const layerCandidates = candidates.filter(candidate => candidate.layer === layer.name);
    const readyCandidates = layerCandidates.filter(candidateIsReady);
    const warningCandidates = layerCandidates.filter(candidate => candidateIsReviewable(candidate) && !candidateIsReady(candidate));
    const invalidCandidates = layerCandidates.filter(candidate => !candidateIsReviewable(candidate));
    const selectedCount = readyCandidates.filter(candidate => state.selectedCandidates.has(candidate.candidateId)).length;
    return `<section class="candidate-layer"><div class="candidate-layer-head"><div><strong>${esc(layer.name)}</strong><span>${readyCandidates.length} 个可采用 · ${warningCandidates.length} 个需修剪</span></div>${badge(`已选 ${selectedCount}/${layer.adoptionTakes}`, selectedCount === layer.adoptionTakes ? "ok" : "warn")}</div>${readyCandidates.length ? `<div class="candidate-grid">${readyCandidates.map(candidate => renderCandidateCard(job, candidate, true, true)).join("")}</div>` : ""}${warningCandidates.length ? `<div class="notice warn"><strong>已保留质量警告候选</strong><span>可以直接播放、比较和本地裁切；通过质量复核前不能应用到 FMOD。</span></div><div class="candidate-grid warning-candidates">${warningCandidates.map(candidate => renderCandidateCard(job, candidate, false, true)).join("")}</div>` : ""}${!readyCandidates.length && !warningCandidates.length ? `<div class="waveform-empty error"><strong>本层没有可评审候选</strong><span>结果存在削波、静音或其他硬错误，请重新生成。</span></div>` : ""}${invalidCandidates.length ? `<details class="invalid-candidates"><summary>硬错误候选 · ${invalidCandidates.length}</summary><div class="candidate-grid">${invalidCandidates.map(candidate => renderCandidateCard(job, candidate, false, false)).join("")}</div></details>` : ""}</section>`;
  }).join("") : `<div class="waveform-empty"><strong>尚无候选</strong><span>生成完成后在这里试听、A/B 和选择 source set。</span></div>`;
  const progress = Math.round((job?.progress || 0) * 100);
  const summary = `<div class="generation-summary" aria-label="生成摘要">${badge(`将生成 ${totalGenerated} 个候选`, "info")}${badge(`需采用 ${totalAdoption} 个`, "warn")}${badge(`最大窗口 ${Number(brief.maxDurationSeconds||brief.targetDurationSeconds||0).toFixed(2)} 秒`)}${badge((brief.durationMode||"LegacyFixed")==="NaturalDecay"?"自然衰减":"固定时长",(brief.durationMode||"LegacyFixed")==="NaturalDecay"?"ok":"warn")}${badge(job ? displayedJobStatus : (hostReady ? "服务就绪" : "服务离线"), displayedJobStatus === "质量失败" ? "error" : displayedJobStatus === "已生成 · 需修剪" ? "warn" : hostReady ? "ok" : "warn")}</div>`;
  const tabs = workspaceTab ? "" : `<div class="generation-tabs" role="tablist">${[["recipe","配方"],["generate","生成"],["candidates","候选与采用"]].map(([id,label]) => `<button type="button" role="tab" aria-selected="${activeTab === id}" class="${activeTab === id ? "active" : ""}" data-generation-tab="${id}">${label}${id === "candidates" && candidates.length ? ` · ${candidates.length}` : ""}</button>`).join("")}</div>`;
  const physicalRecipe = brief.collisionProfile ? renderCollisionRecipe(cue, brief) : renderGenericRecipe(brief);
  const recipePane = `<div class="generation-pane ${activeTab === "recipe" ? "active" : ""}" data-generation-pane="recipe">
    <div class="recipe-primary-actions"><button type="button" class="primary" data-generation-action="optimize">AI 优化英文</button><button type="button" data-generation-action="derive">规则重新派生</button><button type="button" data-generation-next="generate">下一步：配置生成</button></div>
    <div class="recipe-quick-grid"><label class="field"><span>应用声音预设</span><select data-generation-action-select="preset"><option value="">选择预设…</option>${["Footstep","Collision","Landing","Weapon Hit","Magic Explosion"].map(item => `<option>${item}</option>`).join("")}</select></label><label class="field"><span>从其他 Cue 复用</span><select data-generation-action-select="reuse"><option value="">选择 Cue…</option>${(state.generationManifest?.recipes || []).filter(item => item.audioCueId !== cue.audioCueId).map(item => `<option value="${esc(item.audioCueId)}">${esc(findCue(item.audioCueId)?.displayName || item.audioCueId)}</option>`).join("")}</select></label></div>
    <div class="layer-template"><strong>声音结构</strong><div role="group">${[["BodyOnly","单层 · Body"],["TransientBody","双层 · 瞬态 + 主体"],["TransientBodyTail","三层 · 瞬态 + 主体 + 尾音"]].map(([id,label])=>`<button type="button" data-layer-template="${id}" class="${brief.layerTemplate===id?"active":""}">${label}</button>`).join("")}</div><p>层是同一次播放的组成部分；浏览器可先同步混合试听，FMOD 采用后成为完整 Event。</p></div>
    <div class="generation-grid">
      ${physicalRecipe}
      <details class="engineering wide"><summary>中文创作意图 · ${esc(String(brief.intentZh || "").slice(0,42) || "自动取自 Cue 语义")}</summary><label class="field"><span>创作意图</span><textarea data-generation-field="intentZh">${esc(brief.intentZh || "")}</textarea></label></details>
      <details class="engineering wide"><summary>模型英文提示词 ${brief.promptModified ? "· 已人工修改" : ""}</summary><label class="field"><span>English Prompt</span><textarea data-generation-field="positivePrompt">${esc(brief.positivePrompt)}</textarea></label><label class="field"><span>Negative Prompt</span><textarea data-generation-field="negativePrompt">${esc(brief.negativePrompt)}</textarea></label></details>
      <details class="engineering wide" open><summary>分层设置</summary><div class="layer-prompt-list">${(brief.layers || []).map((item,index) => `<article class="layer-recipe ${item.enabled?"":"disabled"}"><div><strong>${esc(item.name)}</strong><span>${item.name==="transient"?"定义起音与冲击轮廓":item.name==="tail"?"定义消散与魔法余韵":"承担主体重量与材质"}</span></div><label><input type="checkbox" data-generation-layer-option="${index}" data-layer-option="enabled" ${item.enabled?"checked":""}> 启用</label><label class="field"><span>音量 dB</span><input type="number" min="-24" max="6" step="0.5" value="${item.gainDb}" data-generation-layer-option="${index}" data-layer-option="gainDb"></label><label class="field"><span>延迟 ms</span><input type="number" min="0" max="250" step="1" value="${item.delayMs}" data-generation-layer-option="${index}" data-layer-option="delayMs"></label><label class="field wide"><span>独立 Prompt</span><textarea data-generation-layer="${index}">${esc(item.prompt || "")}</textarea></label></article>`).join("")}</div></details>
    </div>
    <details class="recipe-tools"><summary>配方工具与历史</summary><div class="recipe-toolbar"><button type="button" data-generation-action="restore-saved">恢复已保存</button><button type="button" data-generation-action="restore-initial">恢复初始派生</button><button type="button" data-generation-action="undo">撤销上一版本</button><button type="button" data-generation-action="copy-recipe">复制 Recipe</button><button type="button" data-generation-action="paste-recipe">粘贴 Recipe</button><button type="button" data-generation-action="copy-prompt">复制英文 Prompt</button></div><div class="recipe-history">${(brief.history || []).slice().reverse().map(item => `<article><div><strong>rev ${item.revision}</strong><span>${esc(item.source || "Manual")} · ${esc(item.savedAtUtc || "")}</span></div><p>${esc(shortPromptDiff(item.positivePrompt, brief.positivePrompt))}</p><button type="button" data-generation-history="${item.revision}">恢复此版本</button></article>`).join("") || `<p class="notice">保存修改后会在这里形成历史。</p>`}</div></details>
  </div>`;
  const generationPane = `<div class="generation-pane ${activeTab === "generate" ? "active" : ""}" data-generation-pane="generate">
    ${offlineNotice}
    <section class="generation-quantity"><div class="quantity-head"><div><strong>生成候选数量</strong><span>${brief.layerTemplate === "BodyOnly" ? "单层 Body" : brief.layerTemplate === "TransientBody" ? "双层 Transient + Body" : "三层 Transient + Body + Tail"} · 最终采用数量在“候选与采用”页设置</span></div><div class="quantity-profiles" role="group" aria-label="生成档位">${[["Quick","快速"],["Standard","标准"],["Explore","充分探索"],["Custom","自定义"]].map(([id,label]) => `<button type="button" class="${brief.generationProfile === id ? "active" : ""}" data-generation-profile="${id}"${id === "Custom" ? " disabled" : ""}>${label}</button>`).join("")}</div></div><div class="layer-count-grid">${brief.layers.map((layer,index) => ({layer,index})).filter(item => item.layer.enabled).map(({layer,index}) => `<article><strong>${esc(layer.name)}</strong><label class="field"><span>生成候选</span><input type="number" min="1" max="12" value="${layer.takes}" data-generation-layer-count="${index}" data-count-kind="takes"></label><small>本层最多 12 个；生成后再决定采用几个。</small></article>`).join("")}</div></section>
    <div class="generation-job"><span>Job ${esc(job?.jobId?.slice(0, 10) || "—")} · ${esc(displayedJobStatus)} · ${job?.computeDevice ? `Compute ${esc(job.computeDevice)}${job.gpuPeakMemoryMiB ? ` · Peak ${Number(job.gpuPeakMemoryMiB).toFixed(0)} MiB` : ""}` : `GPU ${esc(job?.gpuState || "VoiceReady")}`} · TTS ${esc(job?.voiceRecoveryStatus || "Ready")}</span><progress max="100" value="${progress}"></progress><strong>${progress}%</strong></div>
    ${voiceServices ? `<div class="voice-service-strip">${voiceServices}</div>` : ""}${job?.failureReason ? `<p class="notice error">${esc(job.failureReason)}</p>` : ""}
    <section class="exploration-actions"><div><strong>小批探索</strong><span>先为每个启用层生成 3 个，听过混合后再补。</span></div><button type="button" class="primary" data-generation-action="explore"${hostReady && !staleRecipe && (!job || terminal) ? "" : " disabled"}>开始探索 · ${Math.min(36,(brief.layers||[]).filter(item=>item.enabled).length*3)} 个</button></section>
    ${job ? `<div class="layer-extension">${(brief.layers||[]).filter(item=>item.enabled).map(layer=>{const count=candidates.filter(item=>item.layer===layer.name).length;const remaining=Math.max(0,12-count);return `<article><div><strong>${esc(layer.name)}</strong><span>已有 ${count} · 还可生成 ${remaining}</span></div><div>${[1,3,6].map(amount=>`<button type="button" data-generation-extend="${esc(layer.name)}" data-extend-count="${amount}"${!terminal||remaining<amount?" disabled":""}>补 ${amount}</button>`).join("")}</div></article>`}).join("")}</div>`:""}
    <div class="generation-actions"><button type="button" data-generation-action="generate"${hostReady && !staleRecipe && (!job || terminal) ? "" : " disabled"}>高级：生成到配置数量 (${totalGenerated})</button><button type="button" data-generation-action="cancel"${hostReady && job && !terminal ? "" : " disabled"}>取消 Job</button><button type="button" data-generation-next="candidates"${candidates.length ? "" : " disabled"}>进入混合与评审</button></div>
    <details class="job-shelf"><summary>最近 Job · ${state.generationJobs.length}</summary>${state.generationJobs.map(item=>`<button type="button" data-restore-job="${esc(item.jobId)}"><strong>${esc(item.jobId.slice(0,10))}</strong><span>${esc(item.status)} · ${item.candidates?.length||0} 个 · ${esc(item.updatedUtc||"")}</span></button>`).join("")||"<p>暂无可恢复 Job</p>"}</details>
  </div>`;
  const applicationIdle = !state.audioApplication || state.audioApplication.terminal;
  const candidatesPane = `<div class="generation-pane ${activeTab === "candidates" ? "active" : ""}" data-generation-pane="candidates">${job?.fake ? `<p class="notice warn">Fake smoke 候选不能采用为正式素材。</p>` : ""}${renderApplicationProgress()}${renderMixConsole(brief,job,candidates)}<div class="candidate-layers">${candidateGroups}</div>${renderAdoptionConfiguration(brief)}<div class="generation-actions sticky-actions"><span>已选 ${state.selectedCandidates.size}/${totalAdoption}</span><button type="button" class="primary" data-generation-action="adopt"${hostReady && job?.status === "Succeeded" && !job.fake && isCandidateSelectionReady(brief, candidates) && applicationIdle ? "" : " disabled"}>保存并应用替换 ${totalAdoption} 个</button></div><p class="waveform-disclaimer">应用完成后可直接同步到游戏；如需内容质量确认，再在右侧记录 Unity / FMOD 试听结果。Space 按当前分析模式控制源素材或 FMOD 试听。</p></div>`;
  return `<div class="generation-panel">
    <div class="generation-head"><div><strong>Authoring AI Assist · 提示词配方</strong><span>${esc(hostText)} · ${esc(brief.derivationProvider || "RuleDerived")} · rev ${brief.revision || 1}</span></div>${badge(isRecipeDirty() ? "Recipe 未保存" : "Recipe 已保存", isRecipeDirty() ? "warn" : "ok")}</div>
    ${staleRecipe ? `<p class="notice warn">Cue 或 Event 绑定已变化，Recipe 可能过期；请重新派生后再生成。</p>` : ""}
    ${summary}${tabs}${recipePane}${generationPane}${candidatesPane}
  </div>`;
}

function renderApplicationProgress(){const app=state.audioApplication;if(!app)return"";const stages=[["Saved","保存版本"],["Backup","备份 FMOD"],["FmodApply","更新 Event"],["BuildBanks","Build Banks"],["Mirror","同步 Banks"],["UnityRefresh","Unity 刷新"],["Ready","Snapshot Ready"]],index=stages.findIndex(item=>item[0]===app.stage);return `<section class="application-progress ${app.stage==="Failed"?"failed":""}"><div><strong>${esc(app.message||"正在应用音频版本")}</strong><span>${esc(app.stage)} · ${Number(app.progress||0)}%</span></div><progress max="100" value="${Number(app.progress||0)}"></progress><div class="application-stages">${stages.map((item,i)=>`<span class="${i<=index&&app.stage!=="Failed"?"done":""}">${item[1]}</span>`).join("<i>→</i>")}</div>${app.detail?`<details><summary>技术详情</summary><code>${esc(app.code||"")} ${esc(app.detail)}</code></details>`:""}</section>`}
function renderAdoptionHistory(cue, eventDef, open = false) {
  const sets = (state.generationManifest?.adoptionSets || []).filter(item => item.eventDefinitionId === eventDef.id).slice().sort((a,b) => String(b.createdAtUtc).localeCompare(String(a.createdAtUtc)));
  const eventState = (state.generationManifest?.eventStates || []).find(item => item.eventDefinitionId === eventDef.id);
  const active = eventState?.activeSetId || "";
  const published = eventState?.publishedSetId || "";
  const applicationRunning = state.audioApplication && !state.audioApplication.terminal;
  return `<details class="adoption-history" ${open ? "open" : ""}><summary>音效版本历史 · ${sets.length}</summary><div>${sets.map(set => {
    const isActive = set.setId === active;
    const isApplied = set.status === "Applied";
    const isBaseline = set.sourceType === "OriginalBaseline";
    const isPublished = set.setId === published;
    const canDelete = !isActive && !isBaseline && !isPublished && !applicationRunning && set.status !== "Applying";
    const label = isBaseline ? "原始 FMOD 版本" : isActive && isApplied ? "当前应用版本" : isActive ? "待应用版本" : isPublished ? "已发布历史版本" : "历史版本";
    const action = set.status === "ApplyFailed" ? "重试应用" : isActive && isApplied ? "已应用" : "应用此版本";
    const deleteReason = isBaseline ? "原始基线用于安全恢复，不能删除" : isActive ? "当前应用版本不能删除" : isPublished ? "当前已发布版本不能删除" : applicationRunning || set.status === "Applying" ? "版本应用期间不能删除" : "删除此历史版本";
    return `<article class="${isActive ? "active" : ""}"><div><strong>${label}</strong>${badge(set.status,isApplied ? "ok" : set.status === "ApplyFailed" ? "error" : "")}</div><span>${esc(set.createdAtUtc || "")} · ${set.sources?.length || 0} 个素材 · ${esc(String(set.setId).slice(0,20))}</span><div class="history-sources">${(set.sources || []).slice(0,4).map(source => `<audio controls preload="none" src="/${esc(source.projectRelativePath)}"></audio>`).join("")}</div><div class="history-actions"><button type="button" data-apply-history="${esc(set.setId)}" data-set-hash="${esc(set.setHash)}"${isActive && isApplied || applicationRunning ? " disabled" : ""}>${action}</button><button type="button" class="danger" data-delete-history="${esc(set.setId)}" data-set-hash="${esc(set.setHash)}" title="${esc(deleteReason)}"${canDelete ? "" : " disabled"}>删除</button></div></article>`;
  }).join("") || `<p class="notice">首次应用时会自动保存当前 FMOD 原始版本。</p>`}</div></details>`;
}

function candidateIsReady(candidate) { return candidate?.status === "Ready"; }
function candidateIsReviewable(candidate) { return candidateIsReady(candidate) || candidate?.status === "ReverbLike"; }

function renderCandidateCard(job, candidate, selectable, editable = selectable) {
  const edit = editable ? candidateEditFor(job, candidate) : null;
  const durationMs = Math.round(Number(candidate.durationSeconds || 0) * 1000);
  return `<article class="candidate ${selectable ? "" : editable ? "warning" : "invalid"}">
    <div class="candidate-title"><label><input type="checkbox" data-candidate-id="${esc(candidate.candidateId)}"${state.selectedCandidates.has(candidate.candidateId) ? " checked" : ""}${!selectable || state.candidateReviews.get(candidate.candidateId)==="Reject" ? " disabled" : ""}> ${esc(candidate.layer)} · take ${candidate.take}</label><span>${esc(candidate.status || "Ready")}${candidate.autoTailFadeApplied ? ` · 自动渐隐 ${Number(candidate.autoTailFadeMs||0).toFixed(0)}ms` : ""}</span></div>
    <canvas data-candidate-waveform="${esc(candidate.candidateId)}" width="300" height="54"></canvas>
    <audio controls preload="none" src="${candidateUrl(job.jobId, candidate.candidateId)}"></audio>
    <div class="candidate-duration-chain"><span>原始画布 ${formatDuration(candidate.sourceDurationSeconds||candidate.durationSeconds)}</span><i>→</i><span>最大窗口 ${formatDuration(candidate.maxDurationSeconds||candidate.durationSeconds)}</span><i>→</i><strong>成品 ${formatDuration(candidate.trimmedDurationSeconds||candidate.durationSeconds)}</strong></div>
    <div class="candidate-metrics"><span>${candidate.channels}ch / ${(candidate.sampleRate / 1000).toFixed(0)}k</span><span>Peak ${Number(candidate.peakDbfs).toFixed(1)}</span><span>RMS ${Number(candidate.rmsDbfs).toFixed(1)}</span><span>Clip ${(Number(candidate.rawClippingRatio || 0) * 100).toFixed(2)}%</span>${candidate.autoTailFadeApplied ? `<span>原尾音 ${Number(candidate.originalLateTailRelativeDb||0).toFixed(1)} dB</span><span>自动渐隐 ${Number(candidate.autoTailFadeMs||0).toFixed(0)}ms</span>` : `<span>尾音 ${Number(candidate.lateTailRelativeDb||0).toFixed(1)} dB</span>`}<span>${candidate.decayReached?`衰减 ${Number(candidate.decayTimeMs||0).toFixed(0)}ms`:"未自然结束"}</span><span>Crest ${Number(candidate.crestFactorDb || 0).toFixed(1)}dB</span><span>Flat ${Number(candidate.spectralFlatness || 0).toFixed(2)}</span></div>
    ${editable ? `<details class="candidate-editor" data-candidate-editor="${esc(candidateEditKey(job.jobId,candidate.candidateId))}"${state.openCandidateEditors.has(candidateEditKey(job.jobId,candidate.candidateId)) ? " open" : ""}><summary><span data-edit-summary="${esc(candidate.candidateId)}">快捷剪辑 · ${Math.round(edit.outMs-edit.inMs)}ms</span></summary><div class="edit-waveform-shell"><canvas class="edit-waveform" data-edit-waveform="${esc(candidate.candidateId)}" width="900" height="150" tabindex="0" aria-label="拖动波形上的入点、出点、淡入和淡出手柄"></canvas><div class="edit-waveform-help"><span><i class="trim-key"></i>上方：裁剪入点 / 出点</span><span><i class="fade-key"></i>下方：淡入结束 / 淡出开始</span></div></div><div class="edit-grid"><label>入点 ms<input type="number" min="0" max="${durationMs-30}" value="${edit.inMs}" data-edit-candidate="${esc(candidate.candidateId)}" data-edit-field="inMs"></label><label>出点 ms<input type="number" min="30" max="${durationMs}" value="${edit.outMs}" data-edit-candidate="${esc(candidate.candidateId)}" data-edit-field="outMs"></label><label>淡入 ms<input type="number" min="0" max="200" value="${edit.fadeInMs}" data-edit-candidate="${esc(candidate.candidateId)}" data-edit-field="fadeInMs"></label><label>淡出 ms<input type="number" min="0" max="200" value="${edit.fadeOutMs}" data-edit-candidate="${esc(candidate.candidateId)}" data-edit-field="fadeOutMs"></label></div><div class="candidate-review"><button type="button" data-edit-action="play" data-candidate="${esc(candidate.candidateId)}">播放选区</button><button type="button" data-edit-action="loop" data-candidate="${esc(candidate.candidateId)}">循环</button><button type="button" data-edit-action="stop" data-candidate="${esc(candidate.candidateId)}">停止</button><button type="button" data-edit-action="auto" data-candidate="${esc(candidate.candidateId)}">自动裁静音</button><button type="button" data-edit-action="undo" data-candidate="${esc(candidate.candidateId)}"${edit.history?.length ? "" : " disabled"}>撤销</button><button type="button" data-edit-action="reset" data-candidate="${esc(candidate.candidateId)}">恢复原始</button></div></details>` : ""}
    ${candidate.status === "ReverbLike" ? `<div class="candidate-repair"><button type="button" class="primary" data-candidate-repair="${esc(candidate.candidateId)}">一键微调到门槛并勾选</button><span>自动寻找最短尾音渐隐，Host 复检通过后才会解锁。</span></div>` : ""}
    ${editable ? `<div class="candidate-review"><button type="button" data-candidate-review="Keep" data-candidate="${esc(candidate.candidateId)}" class="${state.candidateReviews.get(candidate.candidateId)==="Keep"?"active":""}">保留</button><button type="button" data-candidate-review="Reject" data-candidate="${esc(candidate.candidateId)}" class="${state.candidateReviews.get(candidate.candidateId)==="Reject"?"active":""}">拒绝</button><button type="button" data-candidate-review="" data-candidate="${esc(candidate.candidateId)}">未评审</button></div>` : ""}
  </article>`;
}

function renderMixConsole(brief, job, candidates) {
  if (!job || !candidates.some(candidateIsReviewable)) return `<div class="waveform-empty error"><strong>没有可混合候选</strong><span>${candidates.length ? "当前 Job 只有硬错误结果，请重新生成。" : "先在“生成”页开始小批探索。"}</span></div>`;
  const session = currentSession();
  const slot = session.activeMix === "B" ? "B" : "A";
  const mix = slot === "A" ? session.mixA : session.mixB;
  const rows = (brief.layers||[]).filter(item=>item.enabled).map((layer,index)=>{
    const ready = candidates.filter(item=>item.layer===layer.name && candidateIsReviewable(item) && state.candidateReviews.get(item.candidateId)!=="Reject");
    if (!mix[layer.name] && ready.length) mix[layer.name]=ready[0].candidateId;
    return `<article class="mix-layer"><div><strong>${esc(layer.name)}</strong><select data-mix-layer="${esc(layer.name)}">${ready.map(item=>`<option value="${esc(item.candidateId)}"${mix[layer.name]===item.candidateId?" selected":""}>take ${item.take}${state.candidateReviews.get(item.candidateId)==="Keep"?" · Keep":""}</option>`).join("")}</select></div><label><input type="checkbox" data-mix-mute="${esc(layer.name)}"> Mute</label><label><input type="checkbox" data-mix-solo="${esc(layer.name)}"> Solo</label><label>音量 <input type="range" min="-24" max="6" step="0.5" value="${layer.gainDb}" data-mix-gain="${index}"><output>${layer.gainDb} dB</output></label><label>延迟 <input type="number" min="0" max="250" value="${layer.delayMs}" data-mix-delay="${index}"> ms</label></article>`;
  }).join("");
  return `<section class="mix-console"><div class="mix-head"><div><strong>完整音效混合试听</strong><span>各层使用统一时间基准同步启动；设置会随 Recipe 进入 FMOD adoption。</span></div><div><button type="button" data-mix-slot="A" class="${slot==="A"?"active":""}">A</button><button type="button" data-mix-slot="B" class="${slot==="B"?"active":""}">B</button></div></div><div class="mix-layers">${rows}</div><canvas data-mix-waveform width="900" height="76"></canvas><div class="mix-actions"><button type="button" class="primary" data-generation-action="play-mix">▶ 播放混合音效</button><button type="button" data-generation-action="stop-mix">停止</button><button type="button" data-generation-action="random-mix">随机换一组</button><span data-mix-peak>混合波形将在选择后计算</span></div></section>`;
}

function bindGenerationPanel() {
  el.cueForm.querySelectorAll("[data-workspace-tab]").forEach(button => button.addEventListener("click", () => setWorkspaceTab(button.dataset.workspaceTab)));
  el.cueForm.querySelectorAll("[data-generation-action]").forEach(button => button.addEventListener("click", () => generationAction(button.dataset.generationAction)));
  el.cueForm.querySelectorAll("[data-candidate-id]").forEach(input => input.addEventListener("change", () => toggleCandidate(input.dataset.candidateId, input.checked)));
  el.cueForm.querySelectorAll("[data-generation-field]").forEach(input => input.addEventListener("input", () => updateGenerationBrief(input.dataset.generationField, input.value)));
  el.cueForm.querySelectorAll("[data-collision-body-field]").forEach(input => input.addEventListener(input.tagName === "SELECT" ? "change" : "input", () => updateCollisionBody(input.dataset.collisionBody, input.dataset.collisionBodyField, input.value)));
  el.cueForm.querySelectorAll("[data-collision-field]").forEach(button => button.addEventListener("click", () => updateCollisionChoice(button.dataset.collisionScope, button.dataset.collisionField, button.dataset.collisionValue)));
  el.cueForm.querySelectorAll("[data-collision-preset]").forEach(button => button.addEventListener("click", () => applyCollisionPairPreset(button.dataset.collisionPreset)));
  el.cueForm.querySelectorAll("[data-generation-duration]").forEach(input => input.addEventListener("input", () => updateGenerationDuration(input.value, input)));
  el.cueForm.querySelectorAll("[data-generation-duration-exact]").forEach(input => input.addEventListener("change", () => updateGenerationDuration(input.value, input)));
  el.cueForm.querySelectorAll("[data-duration-character]").forEach(button => button.addEventListener("click", () => updateDurationCharacter(button.dataset.durationCharacter)));
  el.cueForm.querySelectorAll("[data-layer-duration]").forEach(input => input.addEventListener("change", () => updateLayerDuration(Number(input.dataset.layerDuration), input.value)));
  el.cueForm.querySelectorAll("[data-generation-layer]").forEach(input => input.addEventListener("input", () => updateGenerationLayer(Number(input.dataset.generationLayer), input.value)));
  el.cueForm.querySelectorAll("[data-generation-history]").forEach(button => button.addEventListener("click", () => restoreRecipeHistory(Number(button.dataset.generationHistory))));
  el.cueForm.querySelectorAll("[data-generation-action-select]").forEach(select => select.addEventListener("change", () => recipeSelectAction(select.dataset.generationActionSelect, select.value)));
  el.cueForm.querySelectorAll("[data-generation-tab]").forEach(button => button.addEventListener("click", () => setGenerationTab(button.dataset.generationTab)));
  el.cueForm.querySelectorAll("[data-generation-next]").forEach(button => button.addEventListener("click", () => setGenerationTab(button.dataset.generationNext)));
  el.cueForm.querySelectorAll("[data-generation-profile]").forEach(button => button.addEventListener("click", () => applyGenerationProfile(button.dataset.generationProfile)));
  el.cueForm.querySelectorAll("[data-adoption-policy]").forEach(button => button.addEventListener("click", () => applyAdoptionPolicy(button.dataset.adoptionPolicy)));
  el.cueForm.querySelectorAll("[data-apply-history]").forEach(button => button.addEventListener("click", () => applyHistorySet(button.dataset.applyHistory,button.dataset.setHash)));
  el.cueForm.querySelectorAll("[data-delete-history]").forEach(button => button.addEventListener("click", () => deleteHistorySet(button.dataset.deleteHistory, button.dataset.setHash)));
  el.cueForm.querySelectorAll("[data-generation-layer-count]").forEach(input => input.addEventListener("input", () => updateGenerationLayerCount(Number(input.dataset.generationLayerCount), input.dataset.countKind, input.value)));
  el.cueForm.querySelectorAll("[data-layer-template]").forEach(button => button.addEventListener("click", () => applyLayerTemplate(button.dataset.layerTemplate)));
  el.cueForm.querySelectorAll("[data-generation-layer-option]").forEach(input => input.addEventListener("input", () => updateLayerOption(Number(input.dataset.generationLayerOption), input.dataset.layerOption, input.type === "checkbox" ? input.checked : input.value)));
  el.cueForm.querySelectorAll("[data-generation-extend]").forEach(button => button.addEventListener("click", () => extendGeneration(button.dataset.generationExtend, Number(button.dataset.extendCount))));
  el.cueForm.querySelectorAll("[data-restore-job]").forEach(button => button.addEventListener("click", () => restoreJob(button.dataset.restoreJob)));
  el.cueForm.querySelectorAll("[data-candidate-review]").forEach(button => button.addEventListener("click", () => reviewCandidate(button.dataset.candidate, button.dataset.candidateReview)));
  el.cueForm.querySelectorAll("[data-candidate-repair]").forEach(button => button.addEventListener("click", () => repairCandidateToThreshold(button.dataset.candidateRepair)));
  el.cueForm.querySelectorAll("[data-edit-candidate]").forEach(input => input.addEventListener("change", () => updateCandidateEdit(input.dataset.editCandidate, input.dataset.editField, input.value)));
  el.cueForm.querySelectorAll("[data-candidate-editor]").forEach(details => details.addEventListener("toggle", () => details.open ? state.openCandidateEditors.add(details.dataset.candidateEditor) : state.openCandidateEditors.delete(details.dataset.candidateEditor)));
  el.cueForm.querySelectorAll("[data-edit-waveform]").forEach(bindCandidateEditWaveform);
  el.cueForm.querySelectorAll("[data-edit-action]").forEach(button => button.addEventListener("click", () => candidateEditAction(button.dataset.editAction, button.dataset.candidate)));
  el.cueForm.querySelectorAll("[data-mix-slot]").forEach(button => button.addEventListener("click", () => switchMixSlot(button.dataset.mixSlot)));
  el.cueForm.querySelectorAll("[data-mix-layer]").forEach(select => select.addEventListener("change", () => updateMixSelection(select.dataset.mixLayer, select.value)));
  el.cueForm.querySelectorAll("[data-mix-gain]").forEach(input => input.addEventListener("input", () => updateMixParameter(Number(input.dataset.mixGain), "gainDb", input.value)));
  el.cueForm.querySelectorAll("[data-mix-delay]").forEach(input => input.addEventListener("input", () => updateMixParameter(Number(input.dataset.mixDelay), "delayMs", input.value)));
  renderCandidateWaveforms();
  renderOfflineMixWaveform();
}

function bindPhysicalPanel() {
  el.cueForm.querySelectorAll("[data-basis-cue]").forEach(button => button.addEventListener("click", () => selectCue(button.dataset.basisCue)));
  el.cueForm.querySelectorAll("[data-coverage-family-id]").forEach(button => button.addEventListener("click", () => selectCoverageFamily(button.dataset.coverageFamilyId)));
  el.cueForm.querySelectorAll("[data-coverage-cell]").forEach(button => button.addEventListener("click", () => selectCoverageMatrixCell(button.dataset)));
  el.cueForm.querySelectorAll("[data-coverage-inspector-action]").forEach(button => button.addEventListener("click", () => coverageInspectorAction(button.dataset.coverageInspectorAction,button.dataset.coverageBasisCue||"")));
  el.cueForm.querySelectorAll("[data-coverage-basis-range]").forEach(input => input.addEventListener("input", () => updateCoverageBasisRange(input)));
  el.cueForm.querySelectorAll("[data-physical-action]").forEach(button => button.addEventListener("click", () => physicalAction(button.dataset.physicalAction, button.dataset.resolvedCue || "")));
  el.cueForm.querySelectorAll("[data-managed-physical-field]").forEach(input => input.addEventListener(input.tagName === "SELECT" ? "change" : "input", () => updateManagedPhysicalDraft(input.dataset.managedPhysicalField,input.value)));
  el.cueForm.querySelectorAll("[data-physical-basis-path]").forEach(input => input.addEventListener("change", () => updatePhysicalBasis(input.dataset.physicalBasisPath,input.value)));
  el.cueForm.querySelectorAll("[data-physical-basis-anchor-field]").forEach(input => input.addEventListener("change", () => updatePhysicalBasisNested(`${input.dataset.physicalBasisAnchor}.${input.dataset.physicalBasisAnchorField}`,input.value)));
  el.cueForm.querySelectorAll("[data-physical-basis-range]").forEach(input => {
    input.addEventListener("input", () => updatePhysicalBasisRangeInput(input));
    input.addEventListener("change", () => updatePhysicalBasisRangeInput(input,true));
  });
  el.cueForm.querySelectorAll("[data-coverage-requirement-field]").forEach(input => input.addEventListener(input.type === "checkbox" ? "change" : input.tagName === "SELECT" ? "change" : "input", () => updateCoverageRequirementField(input)));
  el.cueForm.querySelectorAll("[data-coverage-requirement-material]").forEach(input => input.addEventListener("change", () => updateCoverageRequirementMaterial(input)));
  el.cueForm.querySelectorAll("[data-physical-coverage-action]").forEach(button => button.addEventListener("click", () => physicalCoverageAction(button.dataset.physicalCoverageAction,button.dataset.coverageIndex,button.dataset.coverageFamily||"")));
  el.cueForm.querySelectorAll("[data-physical-family-path]").forEach(input => input.addEventListener("change", () => updatePhysicalFamily(input.closest("[data-family-id]")?.dataset.familyId,input.dataset.physicalFamilyPath,input.value)));
  el.cueForm.querySelectorAll("[data-physical-weight]").forEach(input => input.addEventListener("input", () => updatePhysicalWeight(input.closest("[data-family-id]")?.dataset.familyId,input.dataset.physicalWeight,input.value,input)));
  el.cueForm.querySelectorAll("[data-response-point]").forEach(input => input.addEventListener("change", () => updateResponsePoint(input)));
  el.cueForm.querySelectorAll("[data-physical-fact]").forEach(input => input.addEventListener(input.tagName === "SELECT" ? "change" : "input", () => updatePhysicalFact(input.dataset.physicalFact,input.value,input)));
  el.cueForm.querySelectorAll("[data-physical-normal]").forEach(input => input.addEventListener("input", () => updatePhysicalNormal(input.dataset.physicalNormal,input.value)));
  el.cueForm.querySelectorAll("[data-physical-body-field]").forEach(input => input.addEventListener(input.tagName === "SELECT" ? "change" : "input", () => updatePhysicalBodyFact(input.dataset.physicalBody,input.dataset.physicalBodyField,input.value,input)));
  bindPhysicalAnalysisPanel(el.cueForm);
}
